sys_variable_value.value:
(function execute(inputs, outputs) {
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'JD Architect',
        'JD_DRAFT',
        null,
        inputs.requisition_sys_id,
        'Generated JD for: ' + inputs.role_title + ' (' + inputs.jd_source + ')',
        '5-Section JD draft created with automated bias checking',
        null,
        'Manager approval required before public posting'
    );
})(inputs, outputs);

